          :aria-expanded="addSkillOpen"
          aria-controls="skills-add-drawer"
          @click="addSkillOpen = true"
        >
          <Icon name="plus" :size="16" />
          <span>{{ t('cronSkills.registry.drawerTitle') }}</span>
